import{z as A,x as d,o as e,c as B,q as i,j as o,D as E,d as t,s as l,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Snort / Suricata 规则","description":"","frontmatter":{"title":"Snort / Suricata 规则","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ids-rules.md","filePath":"cs/ids-rules.md","lastUpdated":1791063341000}'),p={name:"cs/ids-rules.md"};function c(u,a,h,m,T,D){const s=d("Mermaid");return e(),B("div",null,[a[2]||(a[2]=i('<h1 id="snort-suricata-规则" tabindex="-1">Snort / Suricata 规则 <a class="header-anchor" href="#snort-suricata-规则" aria-label="Permalink to &quot;Snort / Suricata 规则&quot;">​</a></h1><div class="epigraph"><p>规则把协议字段、内容匹配与流状态写成可部署的谓词。写得好能抓住已知形态；写得太宽则误杀。规则是知识压缩，不是应用规格。</p><footer>—— 据 Snort Users Manual 对规则语言；Suricata 对规则兼容的陈述</footer></div><p>上一课<a href="/cs/ids-ips">IDS/IPS</a>给了盒子。缺口是<strong>规则怎么写才算合同</strong>：协议、端口、内容、流。本课讲形态与维护，不提供针对特定 CVE 的利用匹配教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>特征规则对已知利用有效，对加密与变形弱。缺口是：版本管理、测试流量、禁用噪声规则。Emerging Threats 一类社区集要审查后启用。</p><p><span class="marginnote">「特征规则」翻译成大白话：一条 if 语句——「如果是从这个端口来的 TCP、载荷里出现这几串字节，就报警」。它的上限就是「见过并写下来的样子」，所以本课说规则是知识压缩：规则集是已知攻击的压缩档案，不是对应用的完整理解。</span></p><h3 id="内容匹配的限度" tabindex="-1">内容匹配的限度 <a class="header-anchor" href="#内容匹配的限度" aria-label="Permalink to &quot;内容匹配的限度&quot;">​</a></h3><p>多态与编码让字节特征老化。协议状态比裸字符串稳。</p><p><span class="marginnote">Snort 规则语法公开。课程禁止用规则开发当攻击演练。蜜罐下一课提供另一类观测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一条规则的头与选项（概念：msg、flow、content）。对照 Suricata 多线程。下一课蜜罐。</p><p><span class="marginnote">读规则的顺序感：头（动作 协议 源地址 源端口 → 目的地址 目的端口）回答「在哪看」，选项（msg、flow、content、sid）回答「看什么、看见了说什么」。缺了 <code>flow:established</code> 这类状态约束的字节特征最容易误伤无关流量——误报多半源于头写得太宽。</span></p>',13)),(e(),o(n,null,{default:E(()=>[l(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HDR%5B%22%E5%8D%8F%E8%AE%AE%E4%B8%8E%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20OPT%5B%22%E5%86%85%E5%AE%B9%E4%B8%8E%E6%B5%81%E9%80%89%E9%A1%B9%22%5D%0A%20%20OPT%20--%3E%20ALERT%5B%22%E5%91%8A%E8%AD%A6%E6%88%96%E4%B8%A2%E5%BC%83%22%5D%0A%20%20OPT%20--%3E%20TUNE%5B%22%E6%B5%8B%E8%AF%95%E5%87%8F%E5%B0%91%E8%AF%AF%E6%8A%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"签名是过时的知识。要与威胁情报和下下一课 ATT&CK 映射，否则规则集膨胀。蜜罐提供低误报的触点。",-1)),(e(),o(n,null,{default:E(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%BC%96%E5%86%99%E7%AD%BE%E5%90%8D%E8%A7%84%E5%88%99%22%5D%20--%3E%20T%5B%22%E5%9B%9E%E6%94%BE%E6%B5%8B%E8%AF%95%E6%B5%81%E9%87%8F%E9%AA%8C%E8%AF%81%22%5D%0A%20%20T%20--%3E%7C%22%E8%AF%AF%E6%8A%A5%E8%BF%87%E5%A4%9A%22%7C%20T2%5B%22%E6%94%B6%E7%AA%84%EF%BC%9A%E8%A1%A5%E5%8D%8F%E8%AE%AE%E4%B8%8E%E6%B5%81%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20T2%20--%3E%20T%0A%20%20T%20--%3E%7C%22%E5%8F%AF%E9%83%A8%E7%BD%B2%22%7C%20E%5B%22%E5%90%AF%E7%94%A8%E5%B9%B6%E6%8E%A5%E5%85%A5%E5%A8%81%E8%83%81%E6%83%85%E6%8A%A5%22%5D%0A%20%20E%20--%3E%20AGE%5B%22%E5%8F%98%E5%BD%A2%E4%B8%8E%E5%8A%A0%E5%AF%86%E8%AE%A9%E7%89%B9%E5%BE%81%E8%80%81%E5%8C%96%22%5D%0A%20%20AGE%20--%3E%20RET%5B%22%E5%AE%A1%E6%9F%A5%E5%90%8E%E6%9B%BF%E6%8D%A2%E6%88%96%E4%B8%8B%E7%BA%BF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">规则集膨胀为什么危险：几万条规则逐包匹配会拖垮检测吞吐，一条过时规则还会对着每次扫描反复误报。与威胁情报对齐、定期审查下线，维护的其实是「信噪比」——不是规则越多越安全。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写针对生产的攻击规则。蜜罐下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IDS 要规则才认识形态。</li><li>协议状态优于裸字符串；要测试误报。</li><li>加密与变形让特征老化。</li><li>下一课蜜罐。</li><li>出处：Snort Users Manual；Suricata 文档。</li></ul>',5))])}const _=A(p,[["render",c]]);export{S as __pageData,_ as default};
